__global__ void sigmoid(const float* input, float* output, int n) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) {
    return;
  }
  output[i] = 1.0f / (1.0f + expf(-input[i]));
}
